SHA256RNDS2                                                            Two Rounds of SHA256
Performs 2 rounds of SHA256 operation with the first operand holding the initial SHA256 state (C,
D, G, H), the second operand holding the initial SHA256 state (A, B, E, F), and the implicit operand
xmm0 holding a pre-computed sum of the next two double word round 2 message as well as the
corresponding round constants. The resulting SHA256 state (A, B, E, F) is placed in the destination
register.

 A_0 SRC2[127:96];
 B_0 SRC2[95:64];
 C_0 SRC1[127:96];
 D_0 SRC1[95:64];
 E_0 SRC2[63:32];
 F_0 SRC2[31:0];
 G_0 SRC1[63:32];
 H_0 SRC1[31:0];
 K0 XMM0[31: 0];
 K1 XMM0[63: 32];

 FOR i = 0 to 1
 {       A_(i +1) Ch (E_i, F_i, G_i) +Perm1(E_i) +K_i + H_i + Ma(A_i , B_i, C_i) +Perm0(A_i);
         B_(i +1) A_i;
         C_(i +1) B_i ;
         D_(i +1) C_i;
         E_(i +1) Ch (E_i, F_i, G_i) + Perm1(E_i) + K_i + H_i + D_i;
         F_(i +1) E_i ;
         G_(i +1) F_i;
         H_(i +1) G_i;
 }

 DEST[127:96] A_2;
 DEST[95:64] B_2;
 DEST[63:32] E_2;
 DEST[31:0] F_2;



